import Foundation

actor APIClient {
    private let session: URLSession
    private let baseURL: URL

    init(baseURL: URL, session: URLSession = .shared) {
        self.baseURL = baseURL
        self.session = session
    }

    func get<T: Decodable>(_ path: String, as type: T.Type, decoder: JSONDecoder) async throws -> T {
        let (data, response) = try await session.data(from: baseURL.appending(path: path))
        guard (response as? HTTPURLResponse)?.statusCode == 200 else { throw URLError(.badServerResponse) }
        return try decoder.decode(T.self, from: data)
    }
}

import Foundation

struct Money: Hashable, Codable {
    var amount: Decimal
    var currencyCode: String

    static func + (lhs: Money, rhs: Money) -> Money {
        precondition(lhs.currencyCode == rhs.currencyCode)
        return Money(amount: lhs.amount + rhs.amount, currencyCode: lhs.currencyCode)
    }
}

